from pydantic import BaseModel, Field

class PaperCitation(BaseModel):
    """A single paper extracted from a document, including its title and citations to other provided papers."""
    title: str | None = Field(description="The full title of this paper")
    references_provided_papers: list[str] = Field(
        description="Titles of the OTHER provided papers that appear in this paper's reference list"
    )

class Parse(BaseModel):
    papers: list[PaperCitation]
